// Prepare structured WhatsApp Message (Text + Voice Note)
const body = $json.body || $json;
const patientId = body.patientId || '';
const patientName = body.patientName || 'Valued Patient';
const patientPhone = body.patientPhone || body.to_number || '';
const language = body.language || 'Tamil';
const contentType = body.contentType || 'Care Packet (Text + Voice)';
const patientExplanation = body.patientExplanation || 'Please follow your prescribed care plan and take medicines on time.';

const voiceUrl = patientId ? `http://localhost:5173/patients/${patientId}/summary` : 'http://localhost:5173';

const messageBody = `🏥 *St. Jude Memorial Hospital — Post-Discharge Care Plan*\n━━━━━━━━━━━━━━━━━━━━\n👤 *Patient:* ${patientName}\n🌐 *Language:* ${language}\n\n📝 *Care Instructions:*\n${patientExplanation}\n\n🎙️ *Audio Voice Guide (${language}):*\n🔊 Tap to listen to your discharge instructions spoken aloud:\n${voiceUrl}\n━━━━━━━━━━━━━━━━━━━━\n💬 _MedGuideAI Multilingual Follow-up Channel_`;

return [{
  json: {
    patientId,
    recipientPhone: patientPhone,
    recipientName: patientName,
    language,
    contentType,
    formattedMessage: messageBody,
    voiceUrl,
    timestamp: new Date().toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' })
  }
}];

// Optional: If sending real WhatsApp via Meta Cloud API or Twilio, wire HTTP Request node.
// Here we log the successful delivery payload for MedGuideAI frontend.
const payload = $json;

return [{
  json: {
    status: 'Delivered',
    date: payload.timestamp,
    channel: 'WhatsApp',
    language: payload.language,
    contentType: payload.contentType,
    patientId: payload.patientId,
    messageId: 'wamid.' + Math.random().toString(36).substring(2, 15)
  }
}];
